<script setup lang="ts">
import { ref,nextTick,onBeforeUnmount } from 'vue';
import { Terminal } from '@xterm/xterm';
import { FitAddon } from '@xterm/addon-fit';
import '@xterm/xterm/css/xterm.css';
import { api,errorText,socketUrl } from './api';
const props=defineProps<{projectId:string;workspaceRef:string;requirementId?:string}>();
const emit=defineEmits<{error:[message:string]}>();
const host=ref<HTMLDivElement>();const id=ref('');const state=ref('未開啟');const command=ref('');const output=ref('');let terminal:Terminal|undefined,fit:FitAddon|undefined,ws:WebSocket|undefined,observer:ResizeObserver|undefined;
async function open(){if(id.value)return;state.value='開啟中';try{const result=await api('/terminals',{projectId:props.projectId,requirementId:props.requirementId,workspaceRef:props.workspaceRef,cols:100,rows:24});id.value=result.id;await nextTick();terminal=new Terminal({fontFamily:'Consolas, "Liberation Mono", monospace',fontSize:12,cursorBlink:true,theme:{background:'#15211f',foreground:'#c9ded1',cursor:'#99e5b5'},convertEol:true,scrollback:3000});fit=new FitAddon();terminal.loadAddon(fit);terminal.open(host.value!);fit.fit();ws=new WebSocket(socketUrl(`/terminals/${encodeURIComponent(id.value)}`));ws.onopen=()=>{state.value='running';resize();};ws.onmessage=event=>{let message:any;try{message=JSON.parse(event.data);}catch{message={type:'terminal.output',data:String(event.data)};}if(message.type==='terminal.output'||message.type==='output'){const data=message.data??message.payload?.data??'';terminal?.write(data);output.value=(output.value+data).slice(-100000);}if(message.type==='terminal.exited'||message.type==='exit')state.value=`exited (${message.exitCode??message.payload?.exitCode??'?'})`;if(message.type==='error')emit('error',message.message??'終端執行失敗');};ws.onclose=()=>state.value='closed';ws.onerror=()=>{state.value='error';emit('error','PTY WebSocket 連線失敗');};terminal.onData(data=>send(data));observer=new ResizeObserver(resize);observer.observe(host.value!);}catch(error){state.value='error';emit('error',errorText(error));}}
function send(data:string){if(ws?.readyState!==WebSocket.OPEN){emit('error','終端尚未連線，輸入未送出');return;}ws.send(JSON.stringify({type:'input',data}));}
function submit(){if(!command.value)return;send(command.value+'\r');command.value='';}
function resize(){if(!fit||!terminal)return;fit.fit();if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:'resize',cols:terminal.cols,rows:terminal.rows}));}
function close(){if(ws?.readyState===WebSocket.OPEN)ws.send(JSON.stringify({type:'close'}));ws?.close();observer?.disconnect();terminal?.dispose();id.value='';state.value='closed';}
onBeforeUnmount(()=>{ws?.close();observer?.disconnect();terminal?.dispose();});
</script>
<template><section class="panel terminal-panel"><div class="panel-heading"><div><span class="eyebrow">WORKSPACE / PTY</span><h2>專案終端機</h2></div><div class="button-row"><span class="tag">{{state}}</span><button v-if="id" class="button small" @click="close">關閉</button><button data-testid="open-terminal" class="button small" :disabled="!!id" @click="open">開啟終端</button></div></div><div class="terminal-location"><span class="mono">{{workspaceRef||'未指定 workspace'}}</span><span data-testid="terminal-session-id" class="mono">{{id}}</span></div><div v-show="id" ref="host" class="xterm-host"></div><p v-if="!id" class="empty-small">開啟後連接工作區內的實際 PTY 程序。</p><form v-if="id" class="terminal-command" @submit.prevent="submit"><span>$</span><input data-testid="terminal-input" v-model="command" autocomplete="off" spellcheck="false" aria-label="終端命令" placeholder="輸入命令，按 Enter 執行"><button class="button small" :disabled="state!=='running'">送出</button></form><details v-if="id" class="output-log"><summary>文字輸出紀錄</summary><pre data-testid="terminal-output">{{output}}</pre></details></section></template>
